:root {
  --bg-page: #0f1117;
  --bg-card: #1a1d27;
  --bg-option: #22263a;
  --bg-option-hover: #2a2f47;
  --bg-option-checked: #1e2d4f;
  --border: #2e3250;
  --border-focus: #4f6ef7;
  --accent: #4f6ef7;
  --accent-hover: #6b87ff;
  --text-primary: #e8eaf6;
  --text-secondary: #8b90b8;
  --text-help: #7a80a8;
  --check-bg: #4f6ef7;
  --check-border: #4f6ef7;
  --radius-card: 14px;
  --radius-option: 8px;
}

body {
  background: var(--bg-page);
  color: var(--text-primary);
  font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 48px 16px;
}

.quiz-wrapper {
  width: 100%;
  max-width: 640px;
}

.quiz-header {
  margin-bottom: 36px;
  text-align: center;
}

.quiz-header h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--text-primary);
}

.quiz-header p {
  margin-top: 8px;
  font-size: 0.95rem;
  color: var(--text-secondary);
}

/* Form field / question card */
.form-field {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-card);
  padding: 28px 28px 24px;
  margin-bottom: 20px;
}

.question-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
}

.question-number {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--accent);
  background: rgba(79, 110, 247, 0.12);
  padding: 3px 10px;
  border-radius: 20px;
}

.question-label {
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--text-primary);
  line-height: 1.45;
  margin-bottom: 14px;
}

.help-text {
  font-size: 0.85rem;
  color: var(--text-help);
  margin-bottom: 18px;
  display: flex;
  align-items: flex-start;
  gap: 6px;
  line-height: 1.5;
}

.help-text::before {
  content: "ℹ";
  font-size: 0.9rem;
  color: var(--accent);
  flex-shrink: 0;
  margin-top: 1px;
}

/* Options list */
.options-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.option-item label {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  background: var(--bg-option);
  border: 1px solid var(--border);
  border-radius: var(--radius-option);
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease;
  user-select: none;
}

.option-item label:hover {
  background: var(--bg-option-hover);
  border-color: var(--accent);
}

.option-item input[type="checkbox"] {
  appearance: none;
  -webkit-appearance: none;
  width: 18px;
  height: 18px;
  border: 2px solid #4a5070;
  border-radius: 4px;
  flex-shrink: 0;
  position: relative;
  transition: background 0.15s ease, border-color 0.15s ease;
  background: transparent;
}

.option-item input[type="checkbox"]:checked {
  background: var(--check-bg);
  border-color: var(--check-border);
}

.option-item input[type="checkbox"]:checked::after {
  content: '';
  position: absolute;
  left: 3px;
  top: 0px;
  width: 6px;
  height: 10px;
  border: 2px solid #fff;
  border-top: none;
  border-left: none;
  transform: rotate(45deg);
}

.option-item input[type="checkbox"]:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}

.option-item:has(input:checked) label {
  background: var(--bg-option-checked);
  border-color: var(--accent);
}

.option-text {
  font-size: 0.95rem;
  color: var(--text-primary);
  line-height: 1.4;
}

/* Submit */
.quiz-footer {
  margin-top: 8px;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
}

.submit-btn {
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: 8px;
  padding: 13px 32px;
  font-size: 0.975rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease;
  letter-spacing: 0.01em;
}

.submit-btn:hover {
  background: var(--accent-hover);
}

.submit-btn:active {
  transform: scale(0.98);
}

.submit-btn:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 3px;
}

/* Results panel */
.results-panel {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-card);
  padding: 28px;
  margin-top: 24px;
  display: none;
}

.results-panel.visible {
  display: block;
}

.results-panel h2 {
  font-size: 1.2rem;
  font-weight: 700;
  margin-bottom: 6px;
}

.results-score {
  font-size: 2.2rem;
  font-weight: 700;
  color: var(--accent);
  margin-bottom: 16px;
}

.results-breakdown {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.result-item {
  font-size: 0.9rem;
  line-height: 1.5;
  padding: 12px 14px;
  border-radius: var(--radius-option);
  border: 1px solid var(--border);
}

.result-item.correct {
  background: rgba(52, 199, 120, 0.08);
  border-color: #34c778;
  color: #7ee8b2;
}

.result-item.incorrect {
  background: rgba(255, 75, 90, 0.08);
  border-color: #ff4b5a;
  color: #ff8f98;
}

.result-item .result-label {
  font-weight: 600;
  margin-bottom: 4px;
}

.result-item .result-detail {
  color: inherit;
  opacity: 0.85;
}

.retry-btn {
  margin-top: 20px;
  background: transparent;
  color: var(--accent);
  border: 1px solid var(--accent);
  border-radius: 8px;
  padding: 10px 24px;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s ease;
}

.retry-btn:hover {
  background: rgba(79, 110, 247, 0.12);
}

.retry-btn:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 3px;
}
