+const questions = [
+  {
+    id: "q1",
+    text: "Which of the following are statically typed programming languages?",
+    help: "Select all that apply — there may be more than one correct answer.",
+    options: [
+      { value: "java",       label: "Java" },
+      { value: "python",     label: "Python" },
+      { value: "rust",       label: "Rust" },
+      { value: "javascript", label: "JavaScript" },
+    ],
+    correct: new Set(["java", "rust"]),
+  },
+  {
+    id: "q2",
+    text: "Which languages were primarily designed for systems-level programming?",
+    options: [
+      { value: "c",      label: "C" },
+      { value: "ruby",   label: "Ruby" },
+      { value: "rust",   label: "Rust" },
+      { value: "php",    label: "PHP" },
+    ],
+    correct: new Set(["c", "rust"]),
+  },
+  {
+    id: "q3",
+    text: "Which of the following languages support first-class functions?",
+    options: [
+      { value: "javascript", label: "JavaScript" },
+      { value: "python",     label: "Python" },
+      { value: "haskell",    label: "Haskell" },
+      { value: "c",          label: "C" },
+    ],
+    correct: new Set(["javascript", "python", "haskell"]),
+  },
+];
+
+function setsEqual(a, b) {
+  if (a.size !== b.size) return false;
+  for (const v of a) if (!b.has(v)) return false;
+  return true;
+}
+
+function getSelected(questionId) {
+  const boxes = document.querySelectorAll(`input[name="${questionId}"]:checked`);
+  return new Set([...boxes].map(cb => cb.value));
+}
+
+document.getElementById("quiz-form").addEventListener("submit", function (e) {
+  e.preventDefault();
+
+  let score = 0;
+  const breakdown = [];
+
+  for (const q of questions) {
+    const selected = getSelected(q.id);
+    const isCorrect = setsEqual(selected, q.correct);
+    if (isCorrect) score++;
+
+    const correctLabels = q.options
+      .filter(opt => q.correct.has(opt.value))
+      .map(opt => opt.label)
+      .join(", ");
+
+    breakdown.push({
+      text: q.text,
+      isCorrect,
+      correctLabels,
+    });
+  }
+
+  const panel = document.getElementById("results-panel");
+  panel.querySelector(".results-score").textContent =
+    `${score} / ${questions.length}`;
+
+  const list = panel.querySelector(".results-breakdown");
+  list.innerHTML = "";
+
+  breakdown.forEach((item, i) => {
+    const li = document.createElement("li");
+    li.className = `result-item ${item.isCorrect ? "correct" : "incorrect"}`;
+    li.innerHTML = `
+      <div class="result-label" aria-label="Question ${i + 1}: ${item.isCorrect ? "Correct" : "Incorrect"}">
+        ${item.isCorrect ? "✓" : "✗"} Question ${i + 1}
+      </div>
+      <div class="result-detail">
+        Correct answer${item.correctLabels.includes(",") ? "s" : ""}: ${item.correctLabels}
+      </div>`;
+    list.appendChild(li);
+  });
+
+  panel.classList.add("visible");
+  panel.scrollIntoView({ behavior: "smooth", block: "start" });
+  panel.setAttribute("aria-live", "polite");
+});
+
+document.getElementById("retry-btn").addEventListener("click", function () {
+  document.getElementById("quiz-form").reset();
+  const panel = document.getElementById("results-panel");
+  panel.classList.remove("visible");
+  window.scrollTo({ top: 0, behavior: "smooth" });
+});
+
